// Some portions generated by Co-Pilot
import { afterEach, describe, expect, it, vi } from "vitest";
import { fetchPlatformBreakdown } from "../fetchPlatformBreakdown";

const binary = (
  os: string,
  architecture: string,
  image_type: string,
  archive: number,
  installer = 0,
) => ({
  os,
  architecture,
  image_type,
  package: { download_count: archive },
  ...(installer ? { installer: { download_count: installer } } : {}),
});

const response = (body: unknown, status = 200) => ({
  ok: status < 400,
  status,
  json: async () => body,
});

afterEach(() => vi.unstubAllGlobals());

describe("fetchPlatformBreakdown", () => {
  it("pages through releases and aggregates downloads per version and platform", async () => {
    const fullPage = Array.from({ length: 5 }, () => ({
      binaries: [binary("linux", "x64", "jdk", 1)],
    }));
    const fetchMock = vi.fn(async (url: string) => {
      if (url.includes("/21/") && url.includes("page=0"))
        return response(fullPage);
      if (url.includes("/21/") && url.includes("page=1"))
        return response([
          { binaries: [binary("windows", "x64", "jre", 2, 3)] },
        ]);
      if (url.includes("/25/") && url.includes("page=0"))
        return response([{ binaries: [binary("mac", "aarch64", "sbom", 4)] }]);
      return response(null, 404);
    });
    vi.stubGlobal("fetch", fetchMock);

    const { rows } = await fetchPlatformBreakdown([21, 25, 26]);

    expect(fetchMock).toHaveBeenCalledTimes(4);
    expect(rows).toEqual([
      {
        version: 21,
        os: "linux",
        architecture: "x64",
        imageType: "jdk",
        archive: 5,
        installer: 0,
      },
      {
        version: 21,
        os: "windows",
        architecture: "x64",
        imageType: "jre",
        archive: 2,
        installer: 3,
      },
      {
        version: 25,
        os: "mac",
        architecture: "aarch64",
        imageType: "sbom",
        archive: 4,
        installer: 0,
      },
    ]);
  });

  it("throws when the API returns an error", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => response(null, 500)),
    );
    await expect(fetchPlatformBreakdown([21])).rejects.toThrow();
  });
});
